package app.studyhub.config; import app.studyhub.domain.User; import app.studyhub.infrastructure.UserRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration class DevelopmentSeed { @Bean CommandLineRunner seed(UserRepository users,PasswordEncoder encoder){return a->{if(users.findByEmail("harold@studyhub.local").isEmpty()){User u=new User();u.setEmail("harold@studyhub.local");u.setPasswordHash(encoder.encode("ChangeMe123!"));users.save(u);}};} }
